import{z as p,x as r,o as e,c as s,q as t,j as i,D as E,d as B,s as l,S as A}from"./chunks/framework.C8m1ZpeB.js";const k=JSON.parse('{"title":"Ornstein–Uhlenbeck 均值回复","description":"","frontmatter":{"title":"Ornstein–Uhlenbeck 均值回复","date":"2026-09-27T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/ornstein-uhlenbeck.md","filePath":"quant/ornstein-uhlenbeck.md","lastUpdated":1791413859000}'),h={name:"quant/ornstein-uhlenbeck.md"};function o(d,a,D,C,c,m){const n=r("Mermaid");return e(),s("div",null,[a[2]||(a[2]=t('<h1 id="ornstein–uhlenbeck-均值回复" tabindex="-1">Ornstein–Uhlenbeck 均值回复 <a class="header-anchor" href="#ornstein–uhlenbeck-均值回复" aria-label="Permalink to &quot;Ornstein–Uhlenbeck 均值回复&quot;">​</a></h1><div class="epigraph"><p>带弹簧的随机游走：漂移按偏离比例把过程拉回锚点，回复速度定半衰期，噪声定带宽——价差、利率与对数波动的默认动力学。</p><footer>—— 据 Uhlenbeck and Ornstein, Physical Review, 1930</footer></div><p><a href="/quant/unscented-kalman">上一课</a>回答了「给定模型怎么滤状态」；本课退一步问状态自己怎么动。均值回复是最常被引用、也最常被滥用的动力学：\\(dX=\\kappa(\\theta-X)\\,dt+\\sigma\\,dW\\)。回复速度 \\(\\kappa\\)、锚点 \\(\\theta\\)、稳态带宽 \\(\\sigma/\\sqrt{2\\kappa}\\)，三个参数把「价差会不会回来、多久回来、回来时在多大范围晃」全部钉死。<a href="/quant/brownian-motion-paths">布朗运动</a>给出的是无回复的随机游走；加一根看不见的绳，就是 OU。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>配对价差、对数利差、平稳化后的波动率都不该用 GBM 描述——GBM 的漂移与水平无关，偏离没有回程票。OU 的漂移正比于偏离：离锚越远拉力越强。缺的课是「怎么从数据把 \\(\\kappa\\) 估出来」：文献给方程，数据给的是离散采样，两者之间隔着离散化与小样本偏差两道坎。本课只写动力学与估计，不写 Vasicek 与 CIR 的利率定价推导，也不把 OU 宣传成必然盈利的信号。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>等间隔采样把 SDE 化成 AR(1)：\\(X_{t+\\Delta}=\\theta+\\phi(X_t-\\theta)+\\epsilon_t\\)，其中 \\(\\phi=e^{-\\kappa\\Delta}\\)。对离散序列跑 OLS 得 \\(\\hat\\phi\\) 与截距 \\(\\hat a\\)，再换算 \\(\\kappa=-\\ln\\hat\\phi/\\Delta\\)、\\(\\theta=\\hat a/(1-\\hat\\phi)\\)，半衰期 \\(\\ln 2/\\kappa\\)。<span class="marginnote">数字实例：日频价差回归出 \\(\\hat\\phi=0.95\\)，则 \\(\\kappa=-\\ln(0.95)\\approx0.0513\\)，半衰期 \\(\\ln2/0.0513\\approx13.5\\) 个交易日——偏离约两周走完一半回程；稳态标准差若为 1.2 个价差单位，\\(\\pm1.2\\) 只是入场带宽的起点，不是终点。</span></p>',7)),(e(),i(A,null,{default:E(()=>[l(n,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20SPREAD%5B%22%E5%8F%96%E4%BB%B7%E5%B7%AE%E6%88%96%E5%B9%B3%E7%A8%B3%E5%8C%96%E5%BA%8F%E5%88%97%22%5D%20--%3E%20OLS%5B%22AR(1)%20%E5%9B%9E%E5%BD%92%E4%BC%B0%E8%AE%A1%20phi%22%5D%0A%20%20OLS%20--%3E%20CHK%7B%22phi%20%E8%90%BD%E5%9C%A8%200%20%E4%B8%8E%201%20%E4%B9%8B%E9%97%B4%E5%90%97%22%7D%0A%20%20CHK%20--%3E%7C%22%E6%98%AF%22%7C%20CAL%5B%22%E6%8D%A2%E7%AE%97%20kappa%20%E4%B8%8E%E5%8D%8A%E8%A1%B0%E6%9C%9F%22%5D%0A%20%20CHK%20--%3E%7C%22%E5%90%A6%22%7C%20STOP%5B%22%E5%8D%95%E4%BD%8D%E6%A0%B9%E6%88%96%E8%B4%9F%E5%9B%9E%E5%A4%8D%EF%BC%9A%E5%81%9C%EF%BC%8C%E5%85%88%E4%BF%AE%E5%BA%8F%E5%88%97%22%5D%0A%20%20CAL%20--%3E%20BAND%5B%22%E7%94%A8%E7%A8%B3%E6%80%81%E6%A0%87%E5%87%86%E5%B7%AE%E5%AE%9A%E5%B8%A6%E5%AE%BD%22%5D%0A%20%20BAND%20--%3E%20MON%5B%22%E6%BB%9A%E5%8A%A8%E9%87%8D%E4%BC%B0%EF%BC%9A%E5%8F%82%E6%95%B0%E4%BC%9A%E6%BC%82%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>回复力全在漂移项：单位偏离每个单位时间被拉回 \\(\\kappa\\) 的比例，回复是指数式的——前半段快、后半段慢，所以「半衰期」比「回复时间」更诚实。稳态分布是高斯，方差 \\(\\sigma^2/2\\kappa\\)：回复越快、噪声越小，带越窄。交易含义跟着参数走：带宽入场、锚点止盈、半衰期定持仓周期与止损时钟，头寸大小归 <a href="/quant/kelly-sizing">Kelly</a> 的账。<span class="marginnote">直觉类比：OU 像系着皮筋的风筝——风（噪声）把它吹得乱跑，皮筋（回复力）按拉伸比例往回拽；皮筋越硬风筝越贴着锚点小幅抖动，皮筋越松越像断线。交易带宽问的就是：风筝离桩多远时出手。</span></p><p><span class="marginnote">常见误区：把小样本 OLS 的 \\(\\hat\\phi\\) 当无偏估计。错在自回归回归本身——真值接近 1 时向下偏差最重，\\(\\phi=0.98\\) 的序列估出 0.95 相当常见；半衰期从约 34 天被压成 13.5 天，持仓周期与止损时钟跟着全错。补救是给 \\(\\hat\\phi\\) 配区间估计并滚动重估，而不是把单次点估计当常数。</span></p>',3)),(e(),i(A,null,{default:E(()=>[l(n,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20PH%5B%22%E5%9B%9E%E5%BD%92%E5%87%BA%E7%9A%84%20phi%22%5D%20--%3E%20Q1%7B%22phi%20%E4%B8%8D%E5%B0%8F%E4%BA%8E%201%20%E5%90%97%22%7D%0A%20%20Q1%20--%3E%7C%22%E6%98%AF%22%7C%20UR%5B%22%E5%8D%95%E4%BD%8D%E6%A0%B9%EF%BC%9A%E4%BB%B7%E5%B7%AE%E6%B2%A1%E6%9C%89%E5%9B%9E%E5%A4%8D%E5%8A%9B%22%5D%0A%20%20UR%20--%3E%20FIX%5B%22%E5%85%88%E5%81%9A%E5%8D%8F%E6%95%B4%E4%B8%8E%E5%B9%B3%E7%A8%B3%E5%8C%96%EF%BC%8C%E5%88%AB%E7%A1%AC%E6%8B%9F%E5%90%88%22%5D%0A%20%20Q1%20--%3E%7C%22%E5%90%A6%22%7C%20Q2%7B%22phi%20%E6%8E%A5%E8%BF%91%200%20%E5%90%97%22%7D%0A%20%20Q2%20--%3E%7C%22%E6%98%AF%22%7C%20WN%5B%22%E5%9B%9E%E5%A4%8D%E5%8D%B3%E6%97%B6%E5%AE%8C%E6%88%90%EF%BC%9A%E5%BD%93%E5%89%8D%E6%B0%B4%E5%B9%B3%E6%97%A0%E9%A2%84%E6%B5%8B%E5%8A%9B%22%5D%0A%20%20Q2%20--%3E%7C%22%E5%90%A6%22%7C%20TR%5B%22%E5%8F%AF%E4%BA%A4%E6%98%93%E5%8C%BA%EF%BC%9A%E4%BC%B0%E5%8D%8A%E8%A1%B0%E6%9C%9F%E4%B8%8E%E5%B8%A6%E5%AE%BD%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[B(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>OU 是假设不是事实。参数时变：regime 切换后 \\(\\kappa\\) 与 \\(\\theta\\) 一起漂，滚动窗口只是补丁不是治愈；离散采样有限时 \\(\\hat\\phi\\) 还叠一层向下偏，采样间隔越粗越明显。成本改写带宽：理论带宽外扩往返成本再谈入场。<span class="marginnote">数字实例：双边成本 0.15 个价差单位，\\(\\pm1.2\\) 的理论带宽外扩到 \\(\\pm1.35\\) 再入场；半衰期 13.5 天意味着一次往返持仓约两周、年化周转约十次量级，成本一年吃掉一到两个价差单位——带宽设计先过成本这一关。</span>回复节奏定好之后，仓位与风险分配不在本课。下一课换一个量纲：从「状态怎么动」转到「波动本身怎么量」——Garman–Klass 估计量。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>OU 用三个参数钉死均值回复：\\(\\kappa\\) 定半衰期、\\(\\theta\\) 定锚点、\\(\\sigma/\\sqrt{2\\kappa}\\) 定带宽。</li><li>离散化即 AR(1)，OLS 可估，但小样本 \\(\\hat\\phi\\) 向下偏，半衰期常被低估。</li><li>\\(\\phi\\) 接近 1 是单位根，接近 0 是白噪声，两个格子都不该硬拟合。</li><li>带宽设计必须外扩成本；参数时变靠滚动重估缓解。</li><li>出处：Uhlenbeck and Ornstein, <em>Physical Review</em>, 1930；Lo and MacKinlay 对 AR 估计偏差的讨论，1988。</li></ul>',4))])}const u=p(h,[["render",o]]);export{k as __pageData,u as default};
